<?= $this->extend('pos/layout') ?><?= $this->section('content') ?>
<div class="row toolbar"><p><?= count($rows) ?> records in your directory</p><a class="button" href="<?= site_url($entity.'/new') ?>">+ Add <?= $entity==='users'?'staff member':esc(rtrim($entity,'s')) ?></a></div><section class="panel table-wrap"><table><thead><tr><th><?= $entity==='products'?'Product':'Name' ?></th><?php if($entity==='products'): ?><th>Unit price</th><th>Stock</th><?php elseif($entity==='customers'): ?><th>Email</th><th>Phone</th><?php else: ?><th>Username</th><?php endif ?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><div class="identity"><?php $img=$r[$entity==='products'?'image':'avatar']??null; if($img): ?><img src="<?= site_url('media/'.$img) ?>" alt="<?= esc($r['name']??$r['full_name']) ?>"><?php else: ?><span class="placeholder"><?= esc(mb_substr($r['name']??$r['full_name'],0,1)) ?></span><?php endif ?><strong><?= esc($r['name']??$r['full_name']) ?></strong></div></td><?php if($entity==='products'): ?><td>₱<?= number_format((float)$r['price'],2) ?></td><td><span class="badge <?= $r['stock_quantity']<6?'warning':'' ?>"><?= esc($r['stock_quantity']) ?> units</span></td><?php elseif($entity==='customers'): ?><td><?= esc($r['email']) ?></td><td><?= esc($r['phone']?:'—') ?></td><?php else: ?><td><?= esc($r['username']) ?></td><?php endif ?><td><div class="actions"><a href="<?= site_url($entity.'/'.$r['id'].'/edit') ?>">Edit</a><form method="post" action="<?= site_url($entity.'/'.$r['id'].'/delete') ?>" onsubmit="return confirm('Delete this record? This cannot be undone.')"><?= csrf_field() ?><button class="danger">Delete</button></form></div></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="4" class="empty">No records yet. Add your first one to get started.</td></tr><?php endif ?></tbody></table></section><p class="muted">Products and staff referenced in sales are retained to preserve transaction history. Deleting a customer makes their past sales walk-in transactions.</p>
